  "類計1": {
   "src": "試卷・段考課習類題卷",
   "page": "印 2",
   "q": "計算 $\\frac{75^2-36^2}{75^2+75\\times72+36^2}$ 的值。",
   "steps": [
    "分母 $75\\times72=2\\times75\\times36$，所以分母 $=(75+36)^2$",
    "原式 $=\\frac{(75+36)(75-36)}{(75+36)^2}=\\frac{75-36}{75+36}$",
    "$=\\frac{39}{111}=\\frac{13}{37}$"
   ],
   "ans": "$\\frac{13}{37}$"
  },
