  "類計2": {
   "src": "試卷・段考課習類題卷",
   "page": "印 2",
   "key": "$6x^2+11x+15$",
   "q": "若小舜欲解 $A$、$B$ 兩個多項式，但只知道 $A-2B=3x^2+2x+3$，$A-4B=-7x-9$，試問小舜解出的多項式 $A$ 為何？",
   "steps": [
    "$A-2B=3x^2+2x+3$……①，$A-4B=-7x-9$……②",
    "①$-$②：$2B=3x^2+9x+12$",
    "由①：$A=(3x^2+2x+3)+2B$",
    "$=(3x^2+2x+3)+(3x^2+9x+12)=6x^2+11x+15$"
   ],
   "ans": "$A=6x^2+11x+15$"
  },
