  "核1-2概2-1": {
   "src": "試卷・核心概念重點卷",
   "page": "印 1",
   "q": "同類項：多項式中，文字符號及次數均相同的項稱為同類項。\n例 $2x^2+3x+4$ 與 $x^2+7x+5$ 中，$2x^2$ 與＿＿為同類項；$3x$ 與＿＿為同類項。",
   "steps": [
    "$2x^2$ 與 $x^2$ 都是 $x$ 的二次項",
    "$3x$ 與 $7x$ 都是 $x$ 的一次項"
   ],
   "ans": "$x^2$、$7x$"
  },
