  "核1-2概3-1": {
   "src": "試卷・核心概念重點卷",
   "page": "印 1",
   "key": "$-$、$-$、$-$、$-$、$6x^2-2x-2$",
   "q": "多項式的加法（橫式）：先去括號再合併同類項。\n例 $(7x^2-4x+3)+(-x^2+2x-5)$，在 $\\square$ 填入 $+$ 或 $-$。",
   "steps": [
    "$=7x^2-4x+3-x^2+2x-5$",
    "$=(7x^2-x^2)+(-4x+2x)+(3-5)$",
    "$=6x^2-2x-2$"
   ],
   "ans": "$6x^2-2x-2$"
  },
