  "核1-2概3-2": {
   "src": "試卷・核心概念重點卷",
   "page": "印 1",
   "key": "$7$、$-$、$4$、$+$、$2$",
   "q": "多項式的加法（直式）：先按降冪排列，缺項補 $0$，再對齊同類項計算。\n例 用直式計算 $(2x^2-4x+3)+(5x^2-1)$。",
   "steps": [
    "缺項補 $0$：$5x^2+0x-1$",
    "對齊後逐欄相加：$2x^2+5x^2=7x^2$，$-4x+0x=-4x$，$3+(-1)=2$",
    "結果：$7x^2-4x+2$"
   ],
   "ans": "$7x^2-4x+2$"
  },
