  "附精2": {
   "src": "習作・附錄本（精熟題型）",
   "page": "印 14",
   "q": "已知 $A=ax^2+bx-2$、$B=bx^2-3ax+6$、$C=5x^2-13x$，且 $A-B-C$ 為常數多項式，求 $A$。",
   "steps": [
    "常數多項式表示二次項與一次項係數都是 $0$",
    "二次項：$a-b-5=0$，得 $a-b=5$　……①",
    "一次項：$b+3a+13=0$，得 $3a+b=-13$　……②",
    "①$+$②：$4a=-8$，$a=-2$；代回①得 $b=-7$"
   ],
   "ans": "$A=-2x^2-7x-2$"
  },
